    return {q:(params.get('q')||'').slice(0,100), category:T.cats.includes(params.get('category'))?params.get('category'):'',min:numberParam('min'),max:numberParam('max'),stock:params.get('stock')==='1',sort:['price-asc','price-desc','rating','name'].includes(params.get('sort'))?params.get('sort'):'recommended'};
