  function classicUpdateBundle(){let sum=0,count=0;document.querySelectorAll('[name=classic-bundle-product]:checked').forEach(el=>{sum+=products.get(el.value)?.price||0;count++;});const label=document.querySelector('[data-classic-bundle-total]');if(label)label.textContent=`${count} ürün · ${money(sum)}`;const b=document.querySelector('[data-action=classic-bundle-add]');if(b)b.disabled=!count;}
